// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint96 _value) public {
        uint256 fundAmount = 100 ether;
        vm.deal(address(c), fundAmount);
        _value = uint96(bound(_value, 1, fundAmount));

        uint256 balanceBefore = address(c).balance;

        vm.prank(c.owner());
        bool ok = true;
        try c.withdraw(_value) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(address(c).balance < balanceBefore);
        }
    }
}
